with open("config.yml", "r") as file:
    config = yaml.safe_load(file)

BASE_URL = config["api"]["host"]
API_KEY = config["authentication"]["api_key"]
HEADERS = {"Authorization": f"Bearer {API_KEY}"}

# Fixtures
