# Test Functions
@pytest.mark.parametrize(
    "tags, expected_status_code",
    [
        (["pet"], 200),           # Valid tags
        ([], 400),                # Missing required parameter
        (None, 400),              # No tags (should fail with 400)
        (["nonexistent"], 200),   # Valid but no matching data
    ],
)
def test_find_by_tags(api_base_url, tags, expected_status_code):
    """
    Test the /v2/pet/findByTags endpoint with various tag combinations.
    """
    url = f"{api_base_url}/pet/findByTags"
    params = {"tags": tags}

    if tags is None:
        response = requests.get(url, headers=HEADERS)
    else:
        response = requests.get(url, headers=HEADERS, params=params)

    assert response.status_code == expected_status_code

    if expected_status_code == 200:
        # Validate response is an array
        response_data = response.json()
        assert isinstance(response_data, list)

        # Validate each entry in array
